// E-Ticaret Sistemi - Ana Giriş Noktası
// Main Entry Point

// Modelleri içe aktar
"src/models/user.hudhud" ใช้;
"src/models/product.hudhud" ใช้;
"src/models/order.hudhud" ใช้;

// Servisleri içe aktar
"src/services/auth.hudhud" ใช้;
"src/services/payment.hudhud" ใช้;
"src/services/notification.hudhud" ใช้;

// Yardımcı คลาสları içe aktar
"src/utils/validation.hudhud" ใช้;
"src/utils/formatting.hudhud" ใช้;

พิมพ์("============================================================");
พิมพ์("E-Ticaret Sistemi - Modüler Mimari Demo");
พิมพ์("============================================================\n");

// Servis örnekleri oluştur
ตัวแปร authService = ใหม่ AuthService();
ตัวแปร paymentService = ใหม่ PaymentService();
ตัวแปร notificationService = ใหม่ NotificationService();

พิมพ์("1️⃣  KULLANICI KAYDI");
พิมพ์("─────────────────────────────────────────────────────────\n");

// Yeni ใช้ıcı oluştur
ตัวแปร newUser = ใหม่ User("Davut Süleyman", "davut@example.com", "güvenli123");
พิมพ์("Kullanıcı oluşturuldu: " + newUser.bilgi());

// Email จริงla
ถ้า (Validation.email(newUser.email)) {
    พิมพ์("✓ Email geçerli: " + newUser.email);
} มิฉะนั้น {
    พิมพ์("✗ Email geçersiz");
}

// Kullanıcıyı kaydet
ตัวแปร authResult = authService.register(newUser);
ถ้า (authResult.success) {
    พิมพ์("✓ " + authResult.message + " (ID: " + authResult.userId + ")");

    // Hoş geldin bildirimi
    notificationService.send(
        newUser.email,
        "Hoş Geldiniz!",
        "Aramıza hoş geldiniz, " + newUser.name
    );
}

พิมพ์("\n2️⃣  ÜRÜN OLUŞTURMA");
พิมพ์("─────────────────────────────────────────────────────────\n");

// Ürün oluştur
ตัวแปร product = ใหม่ Product("MacBook Pro M3", 45000, 10, "Elektronik");
พิมพ์("Ürün oluşturuldu: " + product.bilgi());

// Fiyat จริงla
ถ้า (Validation.price(product.price)) {
    พิมพ์("✓ Fiyat geçerli: " + Formatting.currency(product.price, "TRY"));
}

// Stok kontrolü
ถ้า (product.inStock()) {
    พิมพ์("✓ Ürün stokta mevcut");
} มิฉะนั้น {
    พิมพ์("✗ Ürün stokta yok");
}

พิมพ์("\n3️⃣  SİPARİŞ OLUŞTURMA");
พิมพ์("─────────────────────────────────────────────────────────\n");

// Sipariş oluştur
ตัวแปร order = ใหม่ Order(
    newUser.id,
    product.id,
    1,
    product.price
);
พิมพ์("Sipariş oluşturuldu: " + order.bilgi());

พิมพ์("\n4️⃣  ÖDEME İŞLEMİ");
พิมพ์("─────────────────────────────────────────────────────────\n");

// Ödeme işle
ตัวแปร paymentResult = paymentService.process(
    order.id,
    order.totalPrice,
    "credit_card"
);

ถ้า (paymentResult.success) {
    พิมพ์("✓ " + paymentResult.message);
    พิมพ์("  İşlem No: " + paymentResult.transactionId);
    พิมพ์("  Tutar: " + Formatting.currency(paymentResult.amount, "TRY"));
    พิมพ์("  Yöntem: " + paymentResult.method);

    // Siparişi onayla
    order.confirm();
    พิมพ์("✓ Sipariş onaylandı: " + order.status);

    // Sipariş onay bildirimi
    notificationService.send(
        newUser.email,
        "Siparişiniz Onaylandı",
        "Sipariş numaranız: " + order.id + " - Toplam: " + Formatting.currency(order.totalPrice, "TRY")
    );
} มิฉะนั้น {
    พิมพ์("✗ Ödeme başarısız: " + paymentResult.error);
}

พิมพ์("\n============================================================");
พิมพ์("✓ E-Ticaret sistemi demo tamamlandı!");
พิมพ์("✓ Modüler, ölçeklenebilir ve bakımı kolay mimari");
พิมพ์("============================================================");

