// Validation Utilities - Doğrulama Fonksiyonları

คลาส Validation {
    คงที่ ฟังก์ชัน email(email) {
        // Basit email จริงlama
        คืนค่า email.length > 5;
    }

    คงที่ ฟังก์ชัน password(password) {
        // Şifre en az 6 karakter olmalı
        คืนค่า password.length >= 6;
    }

    คงที่ ฟังก์ชัน price(price) {
        คืนค่า price > 0;
    }

    คงที่ ฟังก์ชัน phone(phone) {
        // Telefon numarası จริงlama
        คืนค่า phone.length == 10;
    }

    คงที่ ฟังก์ชัน required(value) {
        คืนค่า value.length > 0;
    }
}

