// Formatting Utilities - Formatlama Fonksiyonları

คลาส Formatting {
    คงที่ ฟังก์ชัน currency(amount, currency) {
        ถ้า (currency == "TRY") {
            คืนค่า amount + " ₺";
        } มิฉะนั้น {
            ถ้า (currency == "USD") {
                คืนค่า "$" + amount;
            } มิฉะนั้น {
                ถ้า (currency == "EUR") {
                    คืนค่า "€" + amount;
                } มิฉะนั้น {
                    คืนค่า amount + " " + currency;
                }
            }
        }
    }

    คงที่ ฟังก์ชัน date(date) {
        คืนค่า date;
    }

    คงที่ ฟังก์ชัน phone(phone) {
        // (555) 123-4567 formatı
        คืนค่า "(" + phone + ")";
    }

    คงที่ ฟังก์ชัน number(num) {
        // 1,234,567 formatı
        คืนค่า num;
    }
}

