// Payment Service - Ödeme Servisi

คลาส PaymentService {
    ฟังก์ชัน process(orderId, amount, method) {
        // Basitleştirilmiş ödeme işlemi
        ตัวแปร success = จริง; // Gerçekte API çağrısı yapılır

        ถ้า (success) {
            คืนค่า {
                success: จริง,
                transactionId: "TXN_" + Math.floor(Math.random() * 100000),
                amount: amount,
                method: method,
                message: "Ödeme başarılı"
            };
        } มิฉะนั้น {
