// Authentication Service - Kimlik Doğrulama Servisi

คลาส AuthService {
    ตัวสร้าง() {
        ตัวเอง.userCount = 0;
    }

    ฟังก์ชัน register(user) {
        ตัวเอง.userCount = ตัวเอง.userCount + 1;
        คืนค่า {
            success: จริง,
            userId: user.id,
            message: "Kullanıcı başarıyla kaydedildi"
        };
    }

    ฟังก์ชัน login(email, password) {
        // Basitleştirilmiş login
        คืนค่า {
            success: จริง,
            token: "token_" + Math.floor(Math.random() * 1000),
            message: "Giriş başarılı"
        };
    }

    ฟังก์ชัน logout(token) {
        คืนค่า { success: จริง };
    }

    ฟังก์ชัน verifyToken(token) {
        คืนค่า { valid: จริง, userId: "user_123" };
    }
}

